import '../core/media/theme_catalog.dart';

/// The hosted catalog is generated by `collider-drive-sync`, so a lot of Drive
/// imports arrive named after their source file rather than a curated title:
/// `0_Cat_Rain_1280x720`, `0251d1e0-16a1-49ad-9807-19d1bceac3e9_1080_hd`,
/// `5899755_Landscape_Lake_1920x1080`, `Artist_desk_at_night_202606151527`.
/// Those are fine as slugs but unreadable as a title, so they are humanised
/// before they reach the UI. Curated names ("Tide Concrete", "VisionOS
/// Spatial Room", "Canopy Shafts") are detected as clean and left untouched.
const _kUntitledTheme = 'Untitled Theme';

final _reExt = RegExp(r'\.(mp4|m4a|mp3|jpe?g|png|gif|webp)$', caseSensitive: false);
final _reDup = RegExp(r'\s*\(\d+\)$');
final _reCopy = RegExp(r'\s*[-\s]\s*copy$', caseSensitive: false);
final _reRes = RegExp(
    r'(\d{3,4}\s*[x\u00d7]\s*\d{3,4}|1080[_\s-]?hd|2160[_\s-]?hd|1440[_\s-]?hd|720[_\s-]?hd|4k|8k|uhd|\b(?:hd|sd|medium|preview|trailer|loop)\b)',
    caseSensitive: false);
final _reUuid = RegExp(
    r'^(?:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|[0-9a-f]{16,})[_\s-]*',
    caseSensitive: false);
final _reAllDigits = RegExp(r'^\d+$');
final _reLongDigitRun = RegExp(r'(?:^|\D)\d{8,}(?:\D|$)');

const _smallWords = {
  'a', 'an', 'and', 'as', 'at', 'but', 'by', 'for', 'from', 'in', 'into', 'of',
  'on', 'or', 'the', 'to', 'up', 'with',
};

/// True when [s] reads as a source filename rather than a written title.
bool _looksLikeFilename(String s) {
  if (s.contains('_')) return true;
  if (_reRes.hasMatch(s)) return true;
  if (_reUuid.hasMatch(s)) return true;
  if (_reLongDigitRun.hasMatch(s)) return true;
  if (_reExt.hasMatch(s)) return true;
  // A long all-hyphen run with no spaces is a slug, not a title.
  if (!s.contains(' ') && s.split('-').length > 4) return true;
  return false;
}

String _titleCase(List<String> words) {
  if (words.isEmpty) return _kUntitledTheme;
  final out = <String>[];
  for (var i = 0; i < words.length; i++) {
    final w = words[i];
    if (w.isEmpty) continue;
    final lower = i != 0 && i != words.length - 1 && _smallWords.contains(w.toLowerCase());
    if (lower) {
      out.add(w.toLowerCase());
    } else if (RegExp(r'[A-Z]').hasMatch(w.substring(1))) {
      // Already camel/pascal ("GettyImages", "iPhone"): leave the inside alone.
      out.add(w);
    } else {
      out.add(w[0].toUpperCase() + w.substring(1).toLowerCase());
    }
  }
  return out.isEmpty ? _kUntitledTheme : out.join(' ');
}

/// Turn a catalog `name` into something readable in the UI. Curated titles pass
/// through unchanged; Drive filenames are rewritten ("0_Cat_Rain_1280x720"
/// becomes "Cat Rain", a bare UUID becomes "Untitled Theme").
String humanizeThemeName(String raw) {
  var s = raw.trim();
  if (s.isEmpty || !_looksLikeFilename(s)) return s;

  s = s.replaceFirst(_reDup, '').replaceFirst(_reCopy, '');
  s = s.replaceFirst(_reExt, '');
  s = s.replaceAll(_reRes, ' ');
  s = s.replaceFirst(_reUuid, '');
  s = s.replaceAll(RegExp(r'[_\s]+'), ' ').replaceAll('-', ' ');
  s = s.replaceAll(RegExp(r'[^\w\s.]', unicode: false), ' ');

  final words = s.split(' ').where((w) => w.isNotEmpty).toList();
  while (words.isNotEmpty && _reAllDigits.hasMatch(words.first)) {
    words.removeAt(0);
  }
  while (words.isNotEmpty &&
      _reAllDigits.hasMatch(words.last) &&
      words.last.length >= 6) {
    words.removeLast();
  }
  if (words.every((w) => _reAllDigits.hasMatch(w) || w.length < 2)) {
    return _kUntitledTheme;
  }
  return _titleCase(words);
}

/// One track in a theme pack's 5-track soundscape.
class AmbientTrack {
  final int number;
  final String title;
  final String duration;
  final String mood;

  /// Optional streamable audio URL (absolute). Null when the pack ships titles only.
  final String? audioUrl;

  const AmbientTrack({
    required this.number,
    required this.title,
    required this.duration,
    this.mood = 'Ambient',
    this.audioUrl,
  });

  factory AmbientTrack.fromJson(Map<String, dynamic> j, {Uri? base}) => AmbientTrack(
        number: (j['number'] as num?)?.toInt() ?? 0,
        title: humanizeThemeName((j['title'] as String?) ?? ''),
        duration: (j['duration'] as String?) ?? '',
        mood: (j['mood'] as String?) ?? 'Ambient',
        audioUrl: ThemeCatalog.resolve(j['audio'] as String?, base),
      );

  Map<String, dynamic> toJson() => {
        'number': number,
        'title': title,
        'duration': duration,
        'mood': mood,
        if (audioUrl != null) 'audio': audioUrl,
      };
}

/// A wallpaper theme (free still or premium live pack).
///
/// Media fields hold either an absolute https URL (streamed from the
/// collider-media host) or a bundled asset path. Use [ThemeMedia.isNetwork]
/// to tell them apart; the widgets in `features/theme/theme_living_media.dart`
/// handle both.
class WallpaperTheme {
  final String id;
  final String name;

  /// Poster image (about 720px wide). Used for covers, thumbnails, and as the
  /// first frame while [videoPath] streams in. Historically named assetPath.
  final String assetPath;

  /// Optional looping live wallpaper (H.264 mp4, 720p, muted).
  final String? videoPath;

  /// Optional higher resolution still for full-bleed use (free themes).
  final String? stillPath;

  final bool isPremium;
  final String creator;
  final String tier;
  final String collection;
  final List<AmbientTrack> tracks;
  final String? productId;
  final String? priceLabel;

  const WallpaperTheme({
    required this.id,
    required this.name,
    required this.assetPath,
    this.videoPath,
    this.stillPath,
    this.isPremium = false,
    this.creator = 'Studio Nebula',
    this.tier = 'Standard Spatial',
    this.collection = 'Spatial Ambient Series',
    this.productId,
    this.priceLabel,
    this.tracks = const [],
  });

  /// Slug in the media catalog (same as [id]).
  String get slug => id;

  /// Poster URL or asset path.
  String get posterUrl => assetPath;

  /// Video URL or asset path, when the theme is live.
  String? get videoUrl => videoPath;

  /// Best source for a full-bleed still: [stillPath] when present, else poster.
  String get wallpaperStill => stillPath ?? assetPath;

  bool get isLive => videoPath != null && videoPath!.isNotEmpty;

  factory WallpaperTheme.fromJson(Map<String, dynamic> j, {Uri? base}) {
    final premium = j['premium'] == true;
    final slug = j['slug'] as String;
    final rawName = (j['name'] as String?) ?? slug;
    final tracks = (j['tracks'] as List? ?? const [])
        .whereType<Map>()
        .map((t) => AmbientTrack.fromJson(t.cast<String, dynamic>(), base: base))
        .toList(growable: false);
    return WallpaperTheme(
      id: slug,
      name: humanizeThemeName(rawName),
      assetPath: ThemeCatalog.resolve(j['poster'] as String?, base) ?? ThemeCatalog.offlineWallpaperAsset,
      videoPath: ThemeCatalog.resolve(j['video'] as String?, base),
      stillPath: ThemeCatalog.resolve(j['still'] as String?, base),
      isPremium: premium,
      creator: (j['creator'] as String?) ?? 'Collider Studio',
      tier: (j['tier'] as String?) ?? (premium ? 'Elite 4K Live Pack' : 'Free Spatial Canvas'),
      collection: (j['collection'] as String?) ?? 'Spatial Ambient Series',
      productId: (j['productId'] as String?) ?? (premium ? 'collider.theme.$slug' : null),
      priceLabel: j['price'] as String?,
      tracks: tracks,
    );
  }

  Map<String, dynamic> toJson() => {
        'slug': id,
        'name': name,
        'collection': collection,
        'creator': creator,
        'tier': tier,
        'premium': isPremium,
        'price': priceLabel,
        'productId': productId,
        'poster': assetPath,
        'video': videoPath,
        if (stillPath != null) 'still': stillPath,
        'tracks': tracks.map((t) => t.toJson()).toList(),
      };
}

/// Compatibility facade over [ThemeCatalog] (runtime-loaded catalog).
/// Existing call sites keep working; new code should use ThemeCatalog.instance.
class WallpaperCatalog {
  WallpaperCatalog._();

  static List<WallpaperTheme> get freeThemes => ThemeCatalog.instance.freeThemes;
  static List<WallpaperTheme> get premiumThemes => ThemeCatalog.instance.premiumThemes;
  static WallpaperTheme get defaultTheme => ThemeCatalog.instance.defaultTheme;
}
